function TestimonialsCarousel(){const[active,setActive]=useState(0);const[manualPaused,setManualPaused]=useState(false);const[interacting,setInteracting]=useState(false);const paused=manualPaused||interacting;const touchStart=useRef(null);const carousel=useRef(null);const move=(direction)=>setActive(index=>(index+direction+approvedTestimonials.length)%approvedTestimonials.length);useEffect(()=>{if(paused||matchMedia('(prefers-reduced-motion: reduce)').matches)return;const timer=setInterval(()=>setActive(index=>(index+1)%approvedTestimonials.length),9000);return()=>clearInterval(timer)},[paused]);const endSwipe=(event)=>{if(touchStart.current===null)return;const distance=event.changedTouches[0].clientX-touchStart.current;touchStart.current=null;if(Math.abs(distance)>48)move(distance<0?1:-1)};return <div ref={carousel} className="testimonial-carousel" role="region" aria-roledescription="carousel" aria-label="Client testimonials" onMouseEnter={()=>setInteracting(true)} onMouseLeave={()=>setInteracting(false)} onFocusCapture={()=>setInteracting(true)} onBlurCapture={(event)=>{if(!carousel.current?.contains(event.relatedTarget))setInteracting(false)}} onTouchStart={(event)=>{touchStart.current=event.touches[0].clientX}} onTouchEnd={endSwipe}><div className="testimonial-viewport"><div className="testimonial-track" style={{transform:`translate3d(-${active*100}%,0,0)`}} aria-live={paused?'polite':'off'}>{approvedTestimonials.map(([quote,name,role],index)=><blockquote className="testimonial-slide" key={name} aria-hidden={index!==active}><p>“{quote}”</p><strong>{name}</strong><span>{role}</span></blockquote>)}</div></div><div className="testimonial-controls"><button type="button" className="testimonial-arrow" onClick={()=>move(-1)} aria-label="Previous testimonial">←</button><div className="testimonial-dots" aria-label="Choose a testimonial">{approvedTestimonials.map(([,testimonialName],index)=><button type="button" key={testimonialName} className={index===active?'active':''} onClick={()=>setActive(index)} aria-label={`Show testimonial ${index+1} of ${approvedTestimonials.length}`} aria-current={index===active?'true':undefined}/>)}</div><button type="button" className="testimonial-toggle" onClick={()=>setManualPaused(value=>!value)} aria-label={manualPaused?'Play testimonial slideshow':'Pause testimonial slideshow'}>{manualPaused?'▶':'Ⅱ'}</button><button type="button" className="testimonial-arrow" onClick={()=>move(1)} aria-label="Next testimonial">→</button></div></div>}
