function Veterans(){return <><section className="veterans-stacked-hero"><div className="veterans-hero-image"><img src={A+'veterans-live-hero.webp'} alt="Veteran and military family guidance"/><div className="veterans-hero-heading"><h1>Financial Guidance for Veterans and Military Families</h1></div></div></section><section className="veteran-problem"><SectionTitle title="The Military Financial System Was Not Built for Civilian Life" text="The Thrift Savings Plan (TSP) is a powerful tool during active service—but once you separate, it becomes one of the most misunderstood assets in your portfolio. Most veterans either leave it stagnant, roll it incorrectly, or expose it to unnecessary market risk during their most critical accumulation window."/><div className="veteran-risks">{[['📉','TSP left in G-Fund earning minimal growth'],['📋','No civilian estate plan after separation'],['🛡️','SGLI coverage dropped with no replacement'],['💸','Retirement income fully exposed to taxes']].map(([icon,text])=><div key={text}><span>{icon}</span><p>{text}</p></div>)}</div></section><section className="dark"><SectionTitle title="The Three Pillars of Veteran Planning"/><Cards items={[{title:'TSP Strategy & Rollovers',text:'Evaluate your Thrift Savings Plan options with precision. We provide clear guidance on structural rollovers, principal protection, and Fixed Indexed Annuity (FIA) frameworks to explain retirement-income options that may reduce exposure to market volatility.',icon:'growth'},{title:'Military Family Estate Planning',text:'Explore protection strategies designed to support household assets and an orderly legacy transfer. Coordinate your military life insurance transitions and access robust legal protection systems built around service realities.',icon:'shield'},{title:'Financial Literacy & Stewardship',text:'Take total ownership of your household legacy. Build a clear, disciplined financial command structure grounded in family responsibility, protection rules, and multi-generational wealth transfer.',icon:'legacy'}]}/></section><section className="cta"><h2>Ready to Take Command of Your Transition?</h2><p>Build a clear plan for your benefits, retirement, protection, and family legacy.</p><div className="cta-actions"><Button href="https://veteranroadmap.wattsunified.com">Start Your Veteran Roadmap</Button><Button href="/schedule/solutions" ghost>Schedule a Veteran Transition Review</Button></div></section></>}
