function Resources(){return <><ImageHero image="resources-live-hero.png" title="The Legacy Playbook and Resource Hub" alt="Legacy Playbook and Wealth Management"/><section className="resource-intro"><SectionTitle eyebrow="Watts Unified Solutions | Resource Center" title="The Legacy Playbook & Resource Hub" text="Tactical tools, strategic calculators, and protective resources curated to eliminate financial blind spots and secure your household infrastructure."/><div className="featured-resource"><span>Featured Asset</span><h2>Know Your Financial Score in 2 Minutes</h2><p>Before our next strategy conversation, map your current protection, retirement income, and legacy priorities. Private and secure.</p><Button href={financialSnapshotUrl}>Start My Financial Snapshot</Button></div></section><ResourceCategory number="01" title="Strategic Calculators" text="Run your numbers. Reveal hidden tax drag, estimate your real spendable income, and map out your fastest path to zero debt." image="calculators.png" alt="Strategic Financial Tools" items={[{title:'Retirement Calculator',text:'Calculate your compound interest and project your future retirement savings. Map out your path to financial freedom.',href:'https://retirementcalculator.wattsunified.com',label:'Access Calculator'},{title:'3 Tax Buckets Dashboard',text:'Audit your retirement exposure. Compare Taxable, Tax-Deferred, and Structured Tax-Advantaged retirement paths.',href:'https://taxbuckets.wattsunified.com',label:'Access Dashboard'},{title:'Debt Free Tool',text:'Structure your payoff strategy, optimize interest savings, and accelerate your path to zero debt.',href:'https://debtfree.wattsunified.com/',label:'Access Tool'}]}/><ResourceCategory number="02" title="Protection & Legacy" text="Build a stronger protection foundation for your family. Identify critical gaps, secure direct coverage, and establish your legal estate documents." image="family.png" alt="Family Legacy and Protection" items={[{title:'Family Protection Checklist',text:'Discover exactly where your family stands. Identify critical gaps in living benefits, market-protected retirement, and generational wealth.',href:'https://familychecklist.wattsunified.com',label:'Get Free Checklist'},{title:'Protect My Family & Estate',text:'Secure direct coverage options in minutes and help protect your household with coverage options that may support tax-advantaged legacy goals.',href:'https://agents.ethoslife.com/invite/35a362',label:'Get Covered Now'},{title:'Legal & Identity Protection',text:'Defend your household and business with on-demand access to top law firms and comprehensive identity theft protection.',href:'https://salexwatts.legalshieldassociate.com/',label:'Access LegalShield'}]}/><ResourceCategory number="03" title="Educational Playbooks" text="Knowledge is only power when applied. Explore our curated video guides and interactive presentations to master your financial strategy." image="education.png" alt="Educational Briefings" items={[{title:'Legacy Playbook',text:'Explore our curated video guides covering Tax-Free Retirement, Protected Growth, and the Million Dollar Baby strategy.',href:'/build-wealth-legacy',label:'Access The Playbook'},{title:'Interactive Strategy Briefings',text:'Access our exclusive suite of interactive, self-guided presentations covering advanced planning and faith-based strategies.',href:'/interactive-briefings',label:'View Presentations'}]}/><section className="cta"><span>Take the Next Step</span><h2>Need a Guided Walkthrough?</h2><p>If you want to move from running numbers on a screen to building a real, executable strategy, let's talk.</p><div className="cta-actions"><Button href="/schedule/solutions">Schedule a Private Review</Button></div></section></>}
function About(){return <div className="about-page"><PageHero title="Meet S. Alex Watts" text="U.S. Army veteran and retirement and legacy specialist helping families and business owners make clearer decisions about protection, income, and the future they want to leave behind." image="https://wattsunified.com/assets/financial-professional/alex.webp"><Button href="/schedule/solutions">Schedule a Private Conversation</Button></PageHero><div className="about-trust" aria-label="Professional values"><span>U.S. Army Veteran</span><span>Faith-Led</span><span>Education-First</span><span>Legacy-Focused</span></div><section className="about-story"><div><h2>Service Shaped the Mission.</h2><p>During my time in the U.S. Army, I learned that preparation, discipline, and clear communication matter most when people are depending on you.</p><p>I carried those principles into my work with families and business owners. Too often, people receive disconnected information without a clear way to bring protection, retirement income, and legacy decisions together.</p><p>Watts Unified Solutions was built to provide an education-first process: listen carefully, identify what matters, explain options plainly, and help each client take the next appropriate step.</p></div></section><section className="about-principles"><SectionTitle title="The Values Behind Watts Unified Solutions"/><p className="about-values-framework">Faith <span aria-hidden="true">+</span> Family <span aria-hidden="true">+</span> Finance <span aria-hidden="true">+</span> Fitness <span aria-hidden="true">+</span> Fun <strong><span aria-hidden="true">=</span> Freedom</strong></p><Cards items={[{title:'Listen & Educate First',text:'Start with your priorities, answer your questions, and make every recommendation understandable.',icon:'people'},{title:'Protect the Foundation',text:'Address the risks that could disrupt your family, income, business, or long-term plans.',icon:'shield'},{title:'Build With Purpose',text:'Coordinate today’s decisions with the future you want to create and the legacy you want to leave.',icon:'legacy'}]}/></section><CTA title="Bring the Pieces Together." text="Schedule a private conversation to connect your protection, retirement, and legacy priorities into one clear direction." href="/schedule/solutions" buttonText="Start My Private Conversation"/></div>}
